(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.3)*20 + Math.cos(y*0.013-t*0.22)*14;
  const w1y = Math.cos(y*0.02-t*0.28)*18 + Math.sin(x*0.016+t*0.33)*12;
  const mx = x+w1x, my = y+w1y;
  const w2x = Math.sin(mx*0.025-t*0.4)*10 + Math.cos(my*0.03+t*0.15)*8;
  const w2y = Math.cos(my*0.022+t*0.35)*9 + Math.sin(mx*0.028-t*0.45)*7;
  const sx = mx+w2x, sy = my+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.07, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.09, 1.7, 0.8],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.055, 2.3, 1.2],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.11, 1.5, 0.9],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.065, 2.6, 1.1],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.08, 1.9, 0.7],
    [80+Math.sin(t*0.7+3)*70, 40+Math.cos(t*0.45)*50, 0.13, 1.3, 1.3],
    [400+Math.cos(t*0.55+2)*60, 200+Math.sin(t*0.65+4)*40, 0.075, 2.1, 0.6]
  ];
  let aS=0, iS=0, cS=0;
  for (const [sX,sY,f,sp,w] of src) {
    const d = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const wv = Math.sin(d*f - t*sp);
    aS += wv*w;
    iS += Math.sin(d*f*0.65 + t*sp*0.55 + 1.5)*w;
    cS += Math.sin(d*f*1.4 - t*sp*0.8 + 2.0)*w*0.3;
  }
  const n = src.length;
  const act = aS/n, inh = iS/n, cou = cS/n;
  const bg = (Math.sin(sx*0.035+sy*0.022+t*0.7) + Math.sin(sx*0.028-sy*0.035+t*1.05))/2
    + Math.sin((sx+sy)*0.1+t*2.2)*0.15 + Math.sin((sx-sy)*0.08-t*1.8)*0.15;
  const dist = Math.sqrt((sx-cx)**2+(sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
  const spiral = (Math.sin(dist*0.045-ang*3.5-t*1.4) + Math.sin(dist*0.035+ang*4.5-t*1.1))*0.35;
  const radial = Math.sin(dist*0.06-t*0.8)*Math.cos(ang*2+t*0.3)*0.2;
  const cross = Math.sin(sx*0.08+t*0.6)*Math.sin(sy*0.08-t*0.5)*0.25;
  const reaction = Math.tanh((act - inh*0.65 + bg*0.25 + spiral + radial + cross*0.5)*2.0);
  const diff = act*act - inh*inh + cou*0.4;
  const pattern = Math.tanh((reaction + diff*0.4 + Math.sin(reaction*3.14)*0.3)*1.8);
  const cell = Math.tanh((Math.sin(sx*0.12)*Math.sin(sy*0.12) + Math.sin((sx+sy)*0.08+t)*0.4 + Math.sin(sx*0.2-t*1.5)*Math.cos(sy*0.18+t*1.2)*0.3)*1.3)*0.25;
  const micro = Math.sin(sx*0.3+t*2)*Math.sin(sy*0.35-t*1.7)*0.08;
  const blend = pattern*0.65 + cell*0.2 + micro;
  const v = blend*0.5+0.5;
  const pal = [
    [5,12,52],[12,45,85],[18,95,120],[25,155,135],
    [120,185,100],[210,195,60],[225,145,55],[195,85,65],
    [140,40,75],[75,18,60],[30,10,48],[5,12,52]
  ];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const lum = 0.82+Math.sin(pattern*Math.PI)*0.18;
  const edge = Math.abs(pattern)>0.65?1.12:Math.abs(pattern)>0.4?1.04:0.95;
  const glow = Math.max(0, Math.sin(reaction*Math.PI*2)*0.15);
  return [
    Math.min(255, ((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge + glow*40)|0),
    Math.min(255, ((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge + glow*25)|0),
    Math.min(255, ((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge + glow*15)|0)
  ];
}
